/* global process, console */
// Generates src/wire/schema.d.ts from the server's OpenAPI snapshot, or with --check fails
// when the generated file, or the copied contract files, are stale.
// The server tree defaults to the Lifestats repository root that contains this fork.
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';
import prettier from 'prettier';

const pkg = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const target = join(pkg, 'src/wire/schema.d.ts');
const copies = {
  'contract/openapi.json': 'core/infrastructure/web_api/openapi.json',
  'contract/span-cases.json': 'docs/ebook-reading/span-cases.json'
};
const serverTree = resolve(process.env.LIFESTATS_SERVER_TREE ?? join(pkg, '../../../..'));
const check = process.argv.includes('--check');
const canonical = (file) => JSON.stringify(JSON.parse(readFileSync(file, 'utf8')));

const schema = JSON.parse(readFileSync(join(pkg, 'contract/openapi.json'), 'utf8'));
const header = '// Generated by scripts/wire.mjs from contract/openapi.json. Do not edit.\n';
const source = header + astToString(await openapiTS(schema));
const options = (await prettier.resolveConfig(target)) ?? {};
const generated = await prettier.format(source, { ...options, filepath: target });

const stale = [];
if (!check) {
  writeFileSync(target, generated);
} else if (!existsSync(target) || readFileSync(target, 'utf8') !== generated) {
  stale.push('src/wire/schema.d.ts differs from contract/openapi.json; run pnpm gen:wire');
}

if (existsSync(join(serverTree, copies['contract/openapi.json']))) {
  for (const [copy, original] of Object.entries(copies)) {
    if (canonical(join(pkg, copy)) !== canonical(join(serverTree, original))) {
      stale.push(`${copy} differs from ${join(serverTree, original)}`);
    }
  }
  console.log(`compared contract copies with ${serverTree}`);
} else {
  console.log(`no server tree at ${serverTree}; set LIFESTATS_SERVER_TREE to compare copies`);
}

if (stale.length) {
  console.error(stale.join('\n'));
  process.exit(1);
}
console.log(check ? 'wire types and contract copies are current' : `wrote ${target}`);
